/**
 * opc-probe · opc-workbench minimal host plugin (phase-0 spike)
 *
 * Proves three things without touching the DSH kernel:
 *   1. Own-profile bundle loading: the opc-workbench profile lists this package
 *      in dsh.profile.bundles and this package's cordis.patch.yml carries the
 *      insert entry that mounts it into the cordis tree.
 *   2. Runtime activation: apply() runs, writes an activation marker, and
 *      registers two loopback webServer routes (health + chain runner).
 *   3. The AgentRuntime target surface: the in-process sessionController is
 *      driven programmatically through create -> prompt -> follow -> cancel,
 *      and the follow stream is reported as ordered protocol-layer frames.
 *
 * Security posture (same as the shipped company-console precedent): plugin
 * routes bypass the host token gate, so this plugin enforces its own
 * same-origin / loopback guard and JSON-only writes. The host webserver row
 * binds 127.0.0.1, so no route is reachable off-machine.
 *
 * No emoji, no decorative icons, no placeholder copy: every response states
 * observable facts.
 */
import { randomUUID } from 'node:crypto'
import { appendFile, mkdir, rename, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

export const name = 'opc-probe'
export const inject = ['webServer', 'sessionController']

const PLUGIN_DIR = dirname(fileURLToPath(import.meta.url))
const DEFAULT_ROUTE_PATH = '/opc-probe/v1/run'
const DEFAULT_HEALTH_PATH = '/opc-probe/v1/health'
const DEFAULT_PROMPT_TEXT = 'ping'

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

/** Compact, evidence-grade summary of one follow frame. */
function summarizeFrame(frame, index, receivedAt) {
  const base = { index, receivedAt }
  if (frame === null || typeof frame !== 'object') return { ...base, type: 'unknown', raw: String(frame) }
  if (frame.type === 'event' && frame.event && typeof frame.event === 'object') {
    const summary = {
      ...base,
      type: 'event',
      eventType: frame.event.type,
      seq: frame.event.seq,
      time: frame.event.time,
      ignorable: frame.event.ignorable === true,
    }
    // getResult derivation evidence: the follow stream itself carries the
    // assistant payload, so a result view needs no separate transport.
    if (frame.event.type === 'assistant/message' || frame.event.type === 'assistant/attempt') {
      summary.dataPreview = JSON.stringify(frame.event.data ?? null).slice(0, 600)
    }
    return summary
  }
  if (frame.type === 'snapshot') {
    const records = Array.isArray(frame.records) ? frame.records : []
    return {
      ...base,
      type: 'snapshot',
      cursor: frame.cursor,
      hasMore: frame.hasMore === true,
      recordCount: records.length,
      recordEventTypes: records.map((record) => record?.event?.type ?? null),
      header: frame.header
        ? {
            id: frame.header.id,
            createdAt: frame.header.createdAt,
            agentPreset: frame.header.agentPreset ?? null,
          }
        : null,
    }
  }
  if (frame.type === 'assistant-stream') return { ...base, type: 'assistant-stream', frameType: frame.frame?.type ?? null }
  return { ...base, type: frame.type ?? 'unknown' }
}

function lastSeq(frames) {
  let seq = null
  for (const frame of frames) if (typeof frame.seq === 'number') seq = frame.seq
  return seq
}

/**
 * Same-origin / loopback gate. Plugin routes have no host auth field, so the
 * plugin must refuse cross-site and cross-origin callers itself, and writes
 * must be application/json (blocks CORS simple-request form posts).
 */
function guardRequest(req) {
  const headers = req.headers || {}
  const site = String(headers['sec-fetch-site'] || '')
  if (site === 'cross-site' || site === 'same-site') {
    return { ok: false, code: 'CROSS_ORIGIN', error: 'refuse cross-site request' }
  }
  const origin = headers.origin
  if (origin) {
    let originHost = ''
    try {
      originHost = new URL(origin).host
    } catch {
      return { ok: false, code: 'CROSS_ORIGIN', error: 'illegal Origin' }
    }
    if (!headers.host || originHost !== headers.host) {
      return { ok: false, code: 'CROSS_ORIGIN', error: 'same-origin check failed' }
    }
  }
  const method = String(req.method || 'GET').toUpperCase()
  if (method !== 'GET' && method !== 'HEAD') {
    const type = String(headers['content-type'] || '')
    if (!type.toLowerCase().startsWith('application/json')) {
      return { ok: false, code: 'UNSUPPORTED_MEDIA', error: 'writes must be application/json' }
    }
  }
  return { ok: true }
}

function json(res, status, payload) {
  const body = JSON.stringify(payload)
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' })
  res.end(body)
}

function readJsonBody(req, maxBytes) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let size = 0
    req.on('data', (chunk) => {
      size += chunk.length
      if (size > maxBytes) {
        reject(new Error('body too large'))
        req.destroy()
        return
      }
      chunks.push(chunk)
    })
    req.on('end', () => {
      if (chunks.length === 0) {
        resolve({})
        return
      }
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')))
      } catch (error) {
        reject(new Error(`invalid JSON body: ${error.message}`))
      }
    })
    req.on('error', reject)
  })
}

/**
 * Drive one full session chain through the in-process sessionController.
 * The LLM is never judged here: evidence is the ordered protocol-layer event
 * stream (snapshot + durable events), which is valid whether or not the model
 * turn completes.
 */
async function runChain(ctx, options) {
  const controller = ctx.sessionController
  const text = String(options.text ?? DEFAULT_PROMPT_TEXT)
  const collectMillis = Number(options.collectMillis ?? 90000)
  const settleMillis = Number(options.settleMillis ?? 10000)
  const frames = []
  const startedAt = new Date().toISOString()
  const t0 = Date.now()

  const created = await controller.create({})
  const sessionId = created.sessionId

  const abort = new AbortController()
  const followLoop = (async () => {
    try {
      let index = 0
      for await (const frame of controller.follow({ address: { kind: 'session', sessionId } }, abort.signal)) {
        frames.push(summarizeFrame(frame, index, Date.now() - t0))
        index += 1
      }
      frames.push({ index, receivedAt: Date.now() - t0, type: 'follow-closed' })
    } catch (error) {
      frames.push({
        index: frames.length,
        receivedAt: Date.now() - t0,
        type: 'follow-error',
        error: error instanceof Error ? error.message : String(error),
      })
    }
  })()

  await controller.prompt(
    {
      requestId: randomUUID(),
      sessionId,
      mode: 'queue',
      content: [{ type: 'text', text }],
    },
    abort.signal,
  )

  await sleep(collectMillis)

  const cancelIndex = frames.length
  const cancel = controller.cancel({ sessionId })
  const cancelledAt = Date.now() - t0

  await sleep(settleMillis)
  abort.abort()
  await followLoop

  const eventFrames = frames.filter((frame) => frame.type === 'event')
  const afterCancel = frames.slice(cancelIndex)
  const seqs = eventFrames.map((frame) => frame.seq).filter((seq) => typeof seq === 'number')
  const orderedBySeq = seqs.every((seq, i) => i === 0 || seq >= seqs[i - 1])
  const eventTypesInOrder = []
  for (const frame of eventFrames) if (!eventTypesInOrder.includes(frame.eventType)) eventTypesInOrder.push(frame.eventType)

  return {
    ok: true,
    startedAt,
    sessionId,
    agentPreset: created.agentPreset ?? null,
    prompt: text,
    timings: { collectMillis, settleMillis, totalMillis: Date.now() - t0 },
    cancel: { accepted: cancel?.accepted === true, at: cancelledAt },
    follow: {
      frameCount: frames.length,
      snapshotSeen: frames.some((frame) => frame.type === 'snapshot'),
      eventCount: eventFrames.length,
      eventTypesInOrder,
      firstSeq: seqs.length > 0 ? seqs[0] : null,
      lastSeq: lastSeq(frames),
      orderedBySeq,
      frames,
    },
    afterCancelFrames: afterCancel,
    newTurnStartAfterCancel: afterCancel.some((frame) => frame.type === 'event' && /^turn[\/._-]?start/i.test(String(frame.eventType))),
  }
}

export function apply(ctx, config = {}) {
  const routePath = config.routePath ?? DEFAULT_ROUTE_PATH
  const healthPath = config.healthPath ?? DEFAULT_HEALTH_PATH
  const maxBodyBytes = Number(config.maxBodyBytes ?? 65536)
  const evidenceDir = join(PLUGIN_DIR, '..', 'evidence')

  ctx.logger?.info?.(`opc-probe: apply() entered; routes ${healthPath} ${routePath}`)

  const web = ctx.get('webServer')
  if (!web || typeof web.register !== 'function') {
    ctx.logger?.warn?.('opc-probe: webServer service absent; plugin stays inactive')
    return
  }

  ctx.effect(() => {
    const disposers = []

    disposers.push(
      web.register({
        kind: 'exact',
        path: healthPath,
        handler: (req, res) => {
          const gate = guardRequest(req)
          if (!gate.ok) {
            json(res, gate.code === 'UNSUPPORTED_MEDIA' ? 415 : 403, { ok: false, code: gate.code, error: gate.error })
            return
          }
          if (String(req.method || 'GET').toUpperCase() !== 'GET') {
            json(res, 405, { ok: false, code: 'METHOD', error: `${healthPath} supports GET only` })
            return
          }
          json(res, 200, { ok: true, plugin: name, active: true, at: new Date().toISOString() })
        },
      }),
    )

    disposers.push(
      web.register({
        kind: 'exact',
        path: routePath,
        handler: async (req, res) => {
          const gate = guardRequest(req)
          if (!gate.ok) {
            json(res, gate.code === 'UNSUPPORTED_MEDIA' ? 415 : 403, { ok: false, code: gate.code, error: gate.error })
            return
          }
          if (String(req.method || 'POST').toUpperCase() !== 'POST') {
            json(res, 405, { ok: false, code: 'METHOD', error: `${routePath} supports POST only` })
            return
          }
          let body = {}
          try {
            body = await readJsonBody(req, maxBodyBytes)
          } catch (error) {
            json(res, 400, { ok: false, code: 'INVALID', error: error.message })
            return
          }
          try {
            const result = await runChain(ctx, { text: body.text, collectMillis: body.collectMillis, settleMillis: body.settleMillis })
            await appendEvidence(evidenceDir, result)
            json(res, 200, { ok: true, result })
          } catch (error) {
            const failure = {
              ok: false,
              stage: 'session-chain',
              error: error instanceof Error ? error.message : String(error),
              at: new Date().toISOString(),
            }
            await appendEvidence(evidenceDir, failure)
            json(res, 500, failure)
          }
        },
      }),
    )

    return () => {
      for (const dispose of disposers) {
        try {
          dispose()
        } catch {
          /* teardown never throws */
        }
      }
    }
  }, 'opc-probe: routes')

  // Activation marker: written during apply(), before any request arrives.
  void (async () => {
    try {
      await mkdir(evidenceDir, { recursive: true })
      const marker = {
        plugin: name,
        active: true,
        routes: [healthPath, routePath],
        at: new Date().toISOString(),
      }
      const target = join(evidenceDir, 'plugin-active-marker.json')
      const temporary = `${target}.${process.pid}.tmp`
      await writeFile(temporary, `${JSON.stringify(marker, null, 2)}\n`, 'utf8')
      await rename(temporary, target)
    } catch (error) {
      ctx.logger?.warn?.(`opc-probe: activation marker write failed: ${error.message}`)
    }
  })()
}

async function appendEvidence(evidenceDir, record) {
  try {
    await mkdir(evidenceDir, { recursive: true })
    const line = `${JSON.stringify({ at: new Date().toISOString(), ...record })}\n`
    await appendFile(join(evidenceDir, 'chain-runs.jsonl'), line, 'utf8')
    const target = join(evidenceDir, 'step6-chain-result.json')
    const temporary = `${target}.${process.pid}.tmp`
    await writeFile(temporary, line, 'utf8')
    await rename(temporary, target)
  } catch (error) {
    // Evidence persistence must never take down the route handler.
    console.error(`opc-probe: evidence append failed: ${error.message}`)
  }
}
